	title 'Quickdraw Auxilary PICS/MAIN'****************************************************************** Quickdraw Auxilary Picture Stuff** Steven E. Glass* Bennet Marks* Art Cabral** Version 1.0    April 8, 1987**     With a little	help from VersionSoft** Version 2.0    May 8, 1987**     Error checking added to picture routines for version 2.0.*     Bug in updating state record when	drawing lines fixed.** Version 2.4d3  May 5, 1988  (for System Disk 3.2d22)** In SetThisShitUp the call _InstallFont is made, yet the Font Manager is* not one of the tools that QDAux is dependent on. We run into problems * from the Finder when someone trys to 'Show Clipboard' when a picture has* just been copied to the clipboard. DrawPicture breaks because _InstallFont* is being called w/o Font Manager loaded. Therefore I put in check for* carry set when call is completed and if set I clean up stack and go on.* (maybe the call shouldn't even be made? I didn't want to take a chance)** 17 May 88	Steven Glass** Added check to above to make sure that the error was a dispatcher error.** 3/15/89	Mensch* Added fastfont font derefing so that this will work with fast fonts!** 15 May 89	Steven Glass** Changed PutPictStuff so it is in two parts.  The first part is now* in QDAux.asm.  The rest is in this file.** 18 May 89	Steven Glass** Changed SaveSomething to closeout the picture and replace* picsave with FFFFFFFF if an error occurs.  This makes* it possible to return an error at close picture time.** At close picture time I look for the ffff.  If we have it,* we return an error.** This should be a lot cleaner than earlier implementations.***************************************************************************************************************************************************************************************************	 Copyright (C) 1986-1989*	 Apple Computer, Inc.*	 All Rights Reserved*****************************************************************	include 'all.macros'	include 'special.macros'	include '::qd:qdequates:core.globals1'	include '::qd:qdequates:core.globals2'	include '::qd:qdequates:region.equs'	include '::qd:qdequates:rect.equs'	include '::qd:qdequates:qd.data.asm'	include 'QDAuxEquates.asm'	include 'play.equs'	include 'pic.equs'; Equates from file	pics.asmToolNumber	equ 18;-----------------------------------------------------------;; Special EquateIncBusyFlg	equ $E10064DecBusyFlg	equ $E10068;-----------------------------------------------------------;; Other Picture equates;PicBumpSize	equ $800InitialPicSize	equ $800;------------------------------------------------------------;; PicVersion Number;; The High nibble is set to indicate Apple II QuickDraw.;; The Low byte is set to two indicating	that we use; word opcodes rather than byte opcodes	like in version; one of the Mac QD	Pictures.;ThisPicVersion	equ $82********************************************************************************************************************************************	title 'Quickdraw Auxilary pics/OPENPICTURE'****************************************************************** OpenPicture**        Space for Handle*        PicFrame Pointer*****************************************************************iOpenPicture	PROC EXPORTOrigD	equ 1RTL1	equ OrigD+2RTL2	equ RTL1+3PicFramePtr	equ RTL2+3PHandle	equ PicFramePtr+4	jsr PicsQDStart;------------------------------------------------------------;; Check to see if picture is already open.;	ldy #o_PicSave	lda [PortRef],y	bne Oops	iny	iny	lda [PortRef],y	beq NotSavingOops		;	ldx #PicAlreadyOpen	jml BusyErr4;------------------------------------------------------------;; So we are not saving a picture right now.  Get on with; it.;NotSaving		;;; First reset the NoPict flag...	phx	ldx #512	lda #NoPictRecord	eor #$FFFF	and <DirtyDPFlags,x	sta <DirtyDPFlags,x	plx	lda #InitialPicSize	; get handle for picture	jsr MyNewHandle	bcc GotHandle1	tax	; error in xHandleError	jml BusyErr4GotHandle1	sta PHandle,s	txa	sta PHandle+2,s	lda #PicSaveRecSize	jsr MyNewHandle	bcc GotHandle2	pha	; save the error code on stack	lda PHandle+4,s	; dispose first handle	pha	lda PHandle+4,s	pha	_DisposeHandle	plx	; get error code off stack	bra HandleErrorGotHandle2		;	ldy #o_PicSave	; save this handle in graf port and	sta [Portref],y	; on stack for user.	sta TEMP	iny	iny	txa	sta [Portref],y	sta TEMP+2;------------------------------------------------------------;; Now I intialize the picture state record and the beginning; of the picture itself.;	jsr DerefTempToTemp2	lda PHandle,s	; first I put the handle	ldy #o_ThePic	; in the state record	sta [TEMP2],y	lda PHandle+2,s	iny	iny	sta [TEMP2],y;------------------------------------------------------------;; Alloc PicClipRgn (and leave on stack for now);	pha	pha	_NewRgn	jsr DerefPicSave	ldy #o_ThePic	; get the handle to	the pic itself	lda [TEMP2],y	sta TEMP	iny	iny	lda [TEMP2],y	sta TEMP+2	jsr DerefTempToTemp2	lda #10	; put size in picture	sta [TEMP2]	lda PicFramePtr+4,s	; plus four because	of rgn handle	sta TEMP	lda PicFramePtr+6,s	sta TEMP+2	ldy #0PicFrameLoop	lda [TEMP],y	iny	iny	sta [TEMP2],y	cpy #8	bcc PicFrameLoop	jsr DerefPicSave	; deref again since	temp and temp2;		; have been reused.	lda #InitialPicSize	; pic max	ldy #o_PicMax	sta [TEMP2],y	iny	iny	lda #^InitialPicSize	sta [TEMP2],y	lda #10	; picindex	ldy #o_PicIndex	sta [TEMP2],y	iny	iny	lda #0	sta [TEMP2],y	ldy #o_PicClipRgn	; piccliprgn (get if off the stack)	pla	sta [TEMP2],y	iny	iny	pla	sta [TEMP2],y	lda #$FFFF	; PicBkPat (white)	ldy #o_PicBkPatBackPatLoop	sta [TEMP2],y	iny	iny	cpy #o_PicBkPat+32	bcc BackPatLoop	ldy #o_PicFontID	; a bunch of text stuff is 0	lda #0	; FontID, TxFace, TxMode, TxSizeTextStuffLoop	sta [TEMP2],y	; SpExtra, ChExtra,	TxLoc	iny	iny	cpy #o_PicFgColor	bcc TextStuffLoop	ldy #o_PicFgColor	; PicFgColor (black)	lda #$0000	sta [TEMP2],y	ldy #o_PicBgColor	; PicBgColor (white)	lda #$FFFF	sta [TEMP2],y	ldy #o_PicPnLoc	; PicPnLoc (0,0)	lda #0	sta [TEMP2],y	iny	iny	sta [TEMP2],y	ldy #o_PicPnSize+2	lda #1	sta [TEMP2],y	dey	dey	sta [TEMP2],y	ldy #o_PicPnMode	; PicPnMode (0)	lda #0	sta [TEMP2],y	ldy #o_PicPnPat	; PicPnPat (Black)	lda #$0000PenPatLoop	sta [TEMP2],y	iny	iny	cpy #o_PicPnPat+32	bcc PenPatLoop	ldy #o_PicPnMask	; PicPnMask (solid)	lda #$FFFFPenMaskLoop	sta [TEMP2],y	iny	iny	cpy #o_PicPnMask+8	bcc PenMaskLoop	ldy #o_PicTheRect	; PicTheRect (0,0,0,0)	lda #0TheRectLoop	sta [TEMP2],y	iny	iny	cpy #o_PicTheRect+8	bcc TheRectLoop	ldy #o_PicOvSize	; PicOvSize (0,0)	lda #0	sta [TEMP2],y	iny	iny	sta [TEMP2],y	ldy #o_PicArcRot	; PicArcRot (0)	lda #0	sta [TEMP2],y	ldy #o_PortRect	; PicOrigin (cur origin)	lda [PortRef],y	ldy #o_PicOrigin	sta [TEMP2],y	ldy #o_PortRect+2	lda [PortRef],y	ldy #o_PicOrigin+2	sta [TEMP2],y;------------------------------------------------------------;; Finished with state record. Put Version into picture;	lda #PicVersion+(ThisPicVersion<<8)	jsr PutPicWord	_hidepen	jml BusyEC4	ENDP	title 'Quickdraw Auxilary pics/CLOSEPICTURE'****************************************************************** ClosePicture**      No inputs.** (The user got the	handle when the picture was opened.)*****************************************************************iClosePicture	PROC EXPORT	ENTRY CloseItOut	jsr PicsQDStart;; To fix the region trashing bug, first thing to do is be sure to zero out the temp storage we; use for the picture handle...	stz <RgnHandleA	stz <RgnHandleA+2	ldy #o_PicSave	lda [PortRef],y	sta TEMP	iny	iny	lda [PortRef],y	sta TEMP+2	ora TEMP	beq NothingToClose	lda Temp+2	cmp #$FFFF	beq CannotClose	lda #0	; call closeing routine with normal flag	jsr CloseItOut	bcs ReturnErrorCannotClose	ldy #o_PicSave	; fix current graf port	lda #0	sta [Portref],y	iny	iny	sta [Portref],y	_showpen	; bump pen vis;----------------------------------------------------------;; Put the port scb into the first word of the picture.;	ldy #2	lda <RgnHandleA+1	; see if rgn A is still NIL	beq @RgnANotSet	; if so it was never set up to anything.. don't use it	lda [RgnHandleA]	sta RgnPtrA	lda [RgnHandleA],y	sta RgnPtrA+2	lda [PortRef]	sta [RgnPtrA]@RgnANotSet	lda Temp+2	cmp #$FFFF	bne @LooksOK	ldx #PictureError	bra ReturnError@LooksOK	NothingToClose	ldx #0ReturnError	jml BusyErr0	;-----------------------------------------------------------;; New entry point to close down a picture.  ;; If the a-reg is 0, then we do the normal close out.; If the a-reg is not 0, then we set the picture size to;    10 to indicate that the picture is no good.;CloseItOut	pha		; save flag on stack	jsr DerefTempToTemp2		pla		; look at flag	beq NormalClose		PushLong #10	bra SizeOnStackNormalClose	ldy #o_PicIndex+2		; get the real picture size	lda [Temp2],y		; and set the handle size to that	pha	dey	dey	lda [Temp2],y	phaSizeOnStack	ldy #o_ThePic+2	lda [TEMP2],y	pha	sta RgnHandleA+2	dey	dey	lda [TEMP2],y	pha	sta RgnHandleA	_SetHandleSize	bcs GetOut		; things are really hosed if this failsNoError	ldy #o_PicClipRgn+2		; get rid of piccliprgn	lda [TEMP2],y	pha	dey	dey	lda [TEMP2],y	pha	_DisposeRgn	pei Temp+2		; get rid of pic save record	pei Temp	_DisposeHandleGetOut	tax	rts	ENDP********************************************************************************************************************************************	title 'Quickdraw Auxilary pics/KILLPICTURE'****************************************************************** KillPicture**       PicHandle** Disposes of the picture handle.*****************************************************************iKillPicture	PROC EXPORTOrigD	equ 1RTL1	equ OrigD+2RTL2	equ RTL1+3PHandle	equ RTL2+3	jsr PicsQDStart	lda PHandle+2,s	pha	lda PHandle+2,s	pha	_DisposeHandle	tax	jml BusyErr4	ENDP********************************************************************************************************************************************	title 'Quickdraw Auxilary pics/DRAWPICTURE'****************************************************************** DrawPicture**        Picture Handle*        Picture Drawing Frame Pointer*** Change History** 18 Jun 87    Steven E. Glass** When pictures are	recorded in one mode and replayed in another* mode, the to rect	is adjusted.  The adjustment being done	was* wrong.  It was doubling or halving the horizontal coordinates* of the torect rather than doubling or	halving the width of* the to rect.** 14 Oct 87    GPhipps* Changed second line of routine rChExtra from* ldy #o_SpExtra to	ldy #o_ChExtra** Version 2.4d3  May 5, 1988  (for System Disk 3.2d22)** In SetThisShitUp the call _InstallFont is made, yet the Font Manager is* not one of the tools that QDAux is dependent on. We run into problems * from the Finder when someone trys to 'Show Clipboard' when a picture has* just been copied to the clipboard. DrawPicture breaks because _InstallFont* is being called w/o Font Manager loaded. Therefore I put in check for* carry set when call is completed and if set I clean up stack and go on.* (maybe the call shouldn't even be made? I didn't want to take a chance)** 17 May 88	Steven Glass** Added check to above to make sure that the error was a dispatcher error.** 4-Jan-91	Dave Lyons** See revision history at top of file.*****************************************************************iDrawPicture	PROC EXPORT*** added 4-Jan-91 DALDirtyFlags	equ $02EC	;offset into QD work area	sta >qdDirPage	tax	;QD direct page location	lda >DirtyFlags,x	sta >oldDirtyFlags	lda #0	sta >DirtyFlags,x	txa*** end of 4-Jan-91 DAL (more below)	phd	; save caller's direct page	pha	; save quickdraw's direct page	jsl IncBusyFlg	tsc	; make room on stack for all these	sec	; vars	sbc #QuickDrawD-1	tcs	tcd	lda PicToDrawH	ora PicToDrawH+2	beq Error	jsl SetThisShitUp	bcs ErrorKeepLooking	jsl GetPicOpCode	; get a new noun	bcs EndOfTape	; no more	jsl DoOpCode	bcc KeepLooking	cmp #0	; second check to get around accidents	beq KeepLookingEndofTape	cmp #PicEmpty	bne SomethingElse	lda #0SomethingElse	pha	jsr CleanItUp	plaError	tax	tsc	; clean up the stack frame	clc	adc #QuickDrawD+2-1	tcs*** added 4-Jan-91 DAL -- restore fastPort status, clear dirty bits	pha	phx	lda >qdDirPage	tax	lda >oldDirtyFlags	and #$8000	sta >DirtyFlags,x	plx	pla*** end of 4-Jan-91 DAL	jml BusyErr8oldDirtyFlags	dc.w 0	;DALqdDirPage	dc.w 0	;DALDoOpCode	sta OpCodeToDo	; save it here for now	and #$f0	lsr a	lsr a	lsr a	tax	jsr (rOpTable,x)	rtlrOpTable	DC.W ParamOp	DC.W ParamOp	DC.W rLineOrText	DC.W rDrawRect	DC.W rDrawRrect	DC.W rDrawOval	DC.W rDrawArc	DC.W rDrawPoly	DC.W rDrawRgn	DC.W rDrawPixel	DC.W rDrawComment*** added Mensch/DAL 28-Nov-90	DC.W rBadOpcode	DC.W rBadOpcode	DC.W rBadOpcode	DC.W rBadOpcode	DC.W rBadOpcoderBadOpcode	lda  #BadOpcodeError	sec	rts*** end of Mensch/DAL 28-Nov-90CleanItUp	ldy #o_ClipRgn+2	lda [CurPortRef],y	pha	dey	dey	lda [CurPortRef],y	pha	_DisposeRgn	pei SavePortHandle+2 ; copy the saved contents of	pei SavePortHandle	; graf port back into current port	pei CurPortRef+2	pei CurPortRef	PushLong #PortSize	_HandToPtr	pei SavePortHandle+2	pei SavePortHandle	_DisposeHandle	pei TheClip+2	pei TheClip	_DisposeRgn	rtsSetThisShitUp		;;------------------------------------------------------------;; Get the port ref into the stack frame	pha	pha	_GetPort	pla	sta CurPortRef	pla	sta CurPortRef+2;------------------------------------------------------------;; Move DestRect into ToRect in StackFrame.  Make sure; that the rect is not empty	ldy #6ToRectLoop	tyx	lda [ToRectPtr],y	sta ToRect,x	dey	dey	bpl ToRectLoop;----------------------------------------------------------;; Get memory for saving port information;NotEmpty		;	lda #PortSize	jsr MyWNewHandle	bcc NoError	rtlNoError	sta SavePortHandle	stx SavePortHandle+2	pei CurPortRef+2	; copy the current port into the	pei CurPortRef	; save area	pei SavePortHandle+2	pei SavePortHandle	PushLong #PortSize	_PtrToHand;------------------------------------------------------------;; No we initialize the play state record.;	ldx #TheRectZeroLoop	stz 0,x	inx	inx	cpx #CurPortRef	bcc ZeroLoop	ldy #o_ClipRgn	lda [CurPortRef],y	sta UserClip	iny	iny	lda [CurPortRef],y	sta UserClip+2	pha	pha	_NewRgn	plx	stx TheClip	plx	stx TheClip+2	bcc GotRgn	rtlGotRgn		;;------------------------------------------------------------;; Initialize the fields in the port	pha	; clip rgn	pha	_NewRgn	bcc GotRgn2	sta 3,s	plx	lda TheClip+2	pha	lda TheClip	pha	_DisposeRgn	pla	sec	rtlGotRgn2		;	ldy #o_ClipRgn	pla	sta [CurPortRef],y	iny	iny	pla	sta [CurPortRef],y	ldy #o_BkPat	; background pattern	lda #$FFFFPortBPLoop	sta [CurPortRef],y	iny	iny	cpy #o_BkPat+32	bcc PortBPLoop	ldy #o_PnPat	; pen pattern	lda #$0000PortPPLoop	sta [CurPortRef],y	iny	iny	cpy #o_PnPat+32	bcc PortPPLoop	ldy #o_PnMask	; pen Mask	lda #$FFFFPortPMaskLoop	sta [CurPortRef],y	iny	iny	cpy #o_PnMask+8	bcc PortPMaskLoop	ldy #o_PnLoc	; pen loc	lda #0	sta [CurPortRef],y	iny	iny	sta [CurPortRef],y;-----------------------------------------------------------;; Cannot set final pen size until the from rect is in place; so it is moved below;;-----------------------------------------------------------	ldy #o_PnMode	; pen mode (0)	lda #0	sta [CurPortRef],y	PushLong #0	; Code put in to check if error returned from this	PushWord #0	; call because when 'Show Clipboard' is called from	_InstallFont	; finder and a picture has just been copied to the	bcc FMInstalled	; clipboard, DrawPicture breaks because the FMgr is		; not installed and this call fails. HY 5/5/88		; get rid of params on stack	cmp #$0003	; is it a dispatcher error?	bcs FMInstalled	pla	; was dipatcher error, clean stack.	pla	plaFMInstalled	ldy #o_FontID	; text font ID 0	lda [CurPortRef],y	sta ThisFontID	iny	iny	lda [CurPortRef],y	sta ThisFontID+2	ldy #o_ArcRot	; ArcRot	lda #0	sta [CurPortRef],y	ldy #o_txFace	; text face	lda #0	sta [CurPortRef],y	sta ThisTextFace	ldy #o_txSize	; text Size	lda #0	sta [CurPortRef],y	sta ThisTextSize	ldy #o_txMode	; text Mode	lda #0	sta [CurPortRef],y	ldy #o_FontFlags	; Font Flags	lda #0	sta [CurPortRef],y	ldy #o_SpExtra	; Space Extra	lda #0	sta [CurPortRef],y	iny	iny	sta [CurPortRef],y	ldy #o_ChExtra	; Char Extra	lda #0	sta [CurPortRef],y	iny	iny	sta [CurPortRef],y	ldy #o_FGColor	; FGColor	lda #0	sta [CurPortRef],y	ldy #o_BgColor	; BGColor	lda #$FFFF	sta [CurPortRef],y;------------------------------------------------------------;; Now I start playing the thing back.;	stz PlayIndex	; init the play index	stz PlayIndex+2	pha	; initialize the PicSize field	pha	pei PicToDrawH+2	pei PicToDrawH	_GetHandleSize	pla	sta PicSize	pla	sta PicSize+2	lda #1	; assume the version is one	sta ThisVersion;----------------------------------------------------------;; See if the ToRect	needs to be adjusted;	jsr GetPicWord	bcs Error0	eor [CurPortRef]	and #$0080	sta ModeChangedFlag	beq NoChange	lda [CurPortRef]	and #$0080	beq ThisModeIs320;; Mode is now 640 so double the width of the toRect;; Changed 18 Jun 87.  Used to just double x coordinates.;	lda ToRect+6	sec	sbc ToRect+2	asl a	clc	adc ToRect+2	sta ToRect+6	bra NoChange;; Mode is now 320 so halve width of torect.;; Changed 18 Jun 87;; Used to halve the	horizontal coordinates.;ThisModeIs320		;	lda ToRect+6	sec	sbc ToRect+2	lsr a	clc	adc ToRect+2	sta ToRect+6NoChange		;;----------------------------------------------------------;; Put the From rect	in place and see if	it is valid.;	pea 0	tdc	clc	adc #FromRect	pha	PushWord #8	jsl CallGetPic	bcs Error8;----------------------------------------------------------;; Check the to and from rects for validity.;	lda ToRect+4	sec	sbc ToRect	bmi CannotDo	lda ToRect+6	sec	sbc ToRect+2	bmi CannotDo	lda FromRect+4	sec	sbc FromRect	bmi CannotDo	lda FromRect+6	sec	sbc FromRect+2	bmi CannotDo;-----------------------------------------------------------;; Fix the fields that must be scaled;	lda #1	; PicPnSize to (1,1) Scaled	pha	pha	jsr ScaleThisPt	ldy #o_PnSize+2	pla	sta [CurPortRef],y	dey	dey	pla	sta [CurPortRef],y	clc	rtlError8	plx	plx	plx	plxCannotDo		;Error0		;	pha	jsr CleanItUp	pla	sec	rtl	ENDP****************************************************************** DerefPicToDraw*****************************************************************DerefPicToDraw	PROC EXPORT	ldy #2	lda [PicToDrawH],y	sta PicToDrawPtr+2	lda [PicToDrawH]	sta PicToDrawPtr	rts	ENDP****************************************************************** ParamOP******************************************************************ParamOp	PROC EXPORT	lda OpCodeToDo	asl a	tax	jmp (paramTable,x)ParamTable********************************************************************************************************************************************;               DC.W    rPicNOP	Import readparams	DC.W readparams********************************************************************************************************************************************	DC.W rClipRgn	DC.W rBkPat	DC.W rtxfont	DC.W rtxface	DC.W rtxmode	DC.W rSpExtra	DC.W rPnSize	DC.W rPnMode	DC.W rPnPat	DC.W rthePat	DC.W rovSize	DC.W rOrigin	DC.W rTxSize	DC.W rFgColor	DC.W rBgColor	DC.W rTxRatio	DC.W rVersion	DC.W rChExtra	DC.W rPnMask	DC.W rArcRot	DC.W rFontFlags	ENDP****************************************************************** rLineOrText** The Line op codes	are $20 through $27* The text op codes	are $28 through $2F** This routine jumps off the the right code for the opcode.*****************************************************************rLineOrText	PROC EXPORT	lda OpCodeToDo	cmp #$28	bcc DoLine	brl rDrawTextDoLine	brl rDrawLine	ENDP****************************************************************** ReadParams** A single procedure that has in it all	the routines that* read the graf port parameters from the picture.*****************************************************************ReadParams	PROC EXPORT****************************************************************** rPicNOP*****************************************************************	Export rPicNOPrPicNOP	rts****************************************************************** rClipRgn*****************************************************************	Export rClipRgnrClipRgn	jsr GetPicRgn	bcs CRError0	phx	; need this handle 4 times	pha	phx	pha	phx	pha	phx	; first I copy the rgn into	pha	; TheClip	pei TheClip+2	pei TheClip	_CopyRgn	bcs CRError12JoinClipRgn		;	jsr MapThisRgn	bcs CRError8	pei UserClip+2	; Third I Intersect	the Rgn with	pei UserClip	; user clip putting	result in	ldy #o_ClipRgn+2	; graf port.	lda [CurPortRef],y	pha	dey	dey	lda [CurPortRef],y	pha	_SectRgn	bcs CRError4	_DisposeRgn	; finally I dispose	of it.CRError0		;	rtsCRError12	plx	plxCRError8	plx	plxCRError4	plx	ply	pha	phy	phx	_DisposeRgn	pla	sec	rts****************************************************************** rOrigin** The two words next in the picture are	used to offset the* FromRect.  After the from rect is offset, we end up with a* new effect clipping region by taking the current TheClip* remapping with the new FromRect and intersecting with the* userclip.  Result	is put in ClipRgn of current port.** To do all this I create a temporary region that is a copy* of the current TheClip.  This is then	pushed on the stack* a number of times	and control is passed to the RgnOp code* above.*****************************************************************	Export rOriginrOrigin	jsr GetPicWord	bcs CRError0	pha	clc	adc FromRect	sta FromRect	pla	clc	adc FromRect+4	sta FromRect+4	jsr GetPicWord	bcs CRError0	pha	clc	adc FromRect+2	sta FromRect+2	pla	clc	adc FromRect+6	sta FromRect+6	pha	pha	_NewRgn	bcs OError4	pla	plx	phx	; put handle on three times for	pha	; later	phx	pha	phx	pha	pei TheClip+2	; now copy orig TheClip into this	pei TheClip	; temp region	phx	; and once more for	copy rgn call	pha	_CopyRgn	bcs CRError12	bra JoinClipRgn	; and join above codeoError4	plx	plx	rts****************************************************************** rBkPat*****************************************************************	Export rBkPatrBkPat	lda #o_BkPat	clc	adc CurPortRef	tax	lda CurPortRef+2	bcc NoCarry1	inc aNoCarry1	pha	phx	PushWord #32	jsl CallGetPic	rts****************************************************************** rTxMode*****************************************************************	Export rTxModerTxMode	jsr getpicword	ldy #o_TxMode	bra PutPortWord****************************************************************** rSpExtra******************************************************************	Export rSpExtrarSpExtra	jsr GetPicLong	ldy #o_SpExtra	bra PutPortLong****************************************************************** rPnSize** Reads the pen size out of the picture	and puts it into* the grafport.*****************************************************************	Export rPnSizerPnSize	jsr getpiclong	bcc PutSizeIn	rtsPutSizeIn	phx	pha	jsr ScaleThisPt	pla	plx	ldy #o_PnSize	bra PutPortLong****************************************************************** rPnMode** Reads the pen mode out of the picture	and puts it in the* grafport.*****************************************************************	Export rPnModerPnMode	jsr getpicword	ldy #o_PnMode	bra PutPortWord****************************************************************** rOvSize*****************************************************************	Export rOvSizerOvSize	jsr GetPicLong	bcs OvError	phx	pha	jsr ScaleThisPt	pla	sta OvalSize	pla	sta OvalSize+2OvError	rts****************************************************************** rFGColor** Reads the FGColor	from the picture and puts it in the* graf port.*****************************************************************	Export rFgColorrFgColor	jsr getpicWord	ldy #o_FGColor	bra PutPortWord****************************************************************** rBGColor** Reads the BGColor	from the picture and puts it in the* graf port.*****************************************************************	Export rBgColorrBgColor	jsr getpicWord	ldy #o_BGColor	bra PutPortWord****************************************************************** rTxRatio** This is a Mac field and I don't know what it does.*****************************************************************	Export rTxRatiorTxRatio	rts****************************************************************** rVersion** Read the byte out	of the picture and put it in to* play state record.*****************************************************************	Export rVersionrVersion	jsr GetPicByte	sta ThisVersion	rts****************************************************************** rChExtra*****************************************************************	Export rChExtrarChExtra	jsr GetPicLong	ldy #o_ChExtra	bra PutPortLong****************************************************************** rArcRot*****************************************************************	Export rArcRotrArcRot	jsr getpicword	ldy #o_ArcRot	bra PutPortWord****************************************************************** rFontFlags*****************************************************************	Export rFontFlagsrFontFlags	jsr getpicword	ldy #o_FontFlags	bra PutPortWord****************************************************************** PutPortLong** Puts the long passed in a,x into the current port at* the offset passed	in y.*****************************************************************	Export PutPortLongPutPortLong		;	bcs LongError	sta [CurPortRef],y	iny	iny	txa	sta [CurPortRef],yLongError	rts****************************************************************** PutPortWord** Puts the word passed in a into the current port at* the offset passed	in y.*****************************************************************PutPortWord		;	bcs WordError	sta [CurPortRef],yWordError	rts****************************************************************** rPnPat** Reads the pen pattern out of the picture and puts it into* the grafport.*****************************************************************	Export rPnPatrPnPat	lda #o_PnPat	clc	adc CurPortRef	tax	lda CurPortRef+2	bcc NoCarry2	inc aNoCarry2	pha	phx	PushWord #32	jsl CallGetPic	rts****************************************************************** rThePat** Reads the pat out	of the picture and puts it down on zero* page.*****************************************************************	Export rthePatrthePat	pea 0	lda QuickDrawD	clc	adc #TheFillPat+256	pha	PushWord #32	jsl CallGetPic	rts****************************************************************** rPnMask*****************************************************************	Export rPnMaskrPnMask	lda #o_PnMask	clc	adc CurPortRef	tax	lda CurPortRef+2	bcc NoCarry3	inc aNoCarry3	pha	phx	PushWord #8	jsl CallGetPic	rts****************************************************************** rTxFont** This is a tricky one.  This field is read into zero page* variable.  I only	make the install font just before I* draw the text.  I	only draw the text after I this and* two other fields read.** The following fields must be read together:**     FontID*     TxFace*     TxSize*****************************************************************	Export rTxFontrTxFont	jsr GetPicLong	sta ThisFontID	stx ThisFontID+2	rts****************************************************************** rTxFace** This is a tricky one.  This field is read into zero page* variable.  I only	make the install font just before I* draw the text.  I	only draw the text after I this and* two other fields read.** The following fields must be read together:**     FontID*     TxFace*     TxSize*****************************************************************	Export rTxFacerTxFace	jsr getpicword	sta ThisTextFace	rts****************************************************************** rTxSize** This is a tricky one.  This field is read into zero page* variable.  I only	make the install font just before I* draw the text.  I	only draw the text after I this and* two other fields read.** The following fields must be read together:**     FontID*     TxFace*     TxSize*****************************************************************	Export rTxSizerTxSize	jsr GetPicWord	sta ThisTextSize	rts	ENDP; *** I don't know what this was, but it chokes asmiigs 1.2 (11-Mar-92 DAL);	%dbg ''***************************************************************** MapThisRgn**      HandleToRgn** This is the central routine that does	all region mapping.** Because of a bug in SystemDisk 1.1 it	does not call MapRgn* for rectangular regions.  It does a MapRect for these.*** RngHandle is passed on stack on input	and stripped on output.****************************************************************MapThisRgn	PROC EXPORT	DefineStackOrigD	wordPtr	longRtsadr	wordRgnHandle	long	pha	pha	phd	tsc	tcd	lda [RgnHandle]	sta Ptr	ldy #2	lda [RgnHandle],y	sta Ptr+2	lda [Ptr]	cmp #10	beq ItsRect	pei RgnHandle+2	pei Rgnhandle	lda OrigD	tcd	jsr PushRectPtrs	_mapRgnGetOut	pld	plx	plx	ply	plx	plx	phy	rtsItsRect		;	lda Ptr	clc	adc #2	tax	lda Ptr+2	bcc NoCarry	inc aNoCarry	pha	phx	lda OrigD	tcd	jsr PushRectPtrs	_MapRect	bra GetOut	ENDP********************************************************************************************************************************************	title 'Quickdraw Auxilary pics/PUTPICTSTUFF'****************************************************************** SaveSomething**   Input:   DrawNoun is on the stack** This routine is only called after PutPictStuff discovers* that the picture is open and something needs to be* saved.** This used to be part of PutPictStuff, but it is now* separate so that the picture code can be segmented.** This is the routine called by the various drawing calls to* to check and see if a picture is being saved to.  If the* picture is being saved to, This routine saves what it needs.* If not it just returns.** 3/10/89	Mensch* Added DirtyFlag set for NoPictRecord field...** 15 May 89	Steven Glass** Broke off from PutPictStuff to allow segmenting.*****************************************************************SaveSomething	PROC EXPORT	ldy #o_pnVis	; first check pen vis	lda [PortRef],y	; if it is less than -1 then	bpl pen_ok	; we don't put it in picture!	cmp #$ffff	bpl pen_okDone	phx	ldx #512	lda <DirtyDPFlags,x	ora #NoPictRecord	sta <DirtyDPFlags,x	plx	pla	; return with noun still in a	clc	; and carry clear	RTLpen_ok		;	lda #$FFFF	cmp Temp+2	bne LooksOK	lda #PictureError	bra QuickExitLooksOK	jsr DerefTempToTemp2 ; deref the picture handle	lda 1,s	; get noun back in a-reg	jsl UpdateStateRec	; compare current graph port with;		; picture state record	bcc AllIsWellAnError	pha	; put error code on stack;; Close out the picture and Put -1 into the picsave field so that ; close picture will not succeed;	ldy #o_PicSave	lda [PortRef],y	sta Temp	iny	iny	lda [PortRef],y	sta Temp+2	lda #$FFFF	jsr CloseItOut		ldy #o_PicSave	lda [PortRef],y	lda #$FFFF	sta [PortRef],y	iny	iny	sta [PortRef],y	pla	; put error code back in a-regQuickExit	plx	; clear off the noun	rtl	; carry is still set.AllIsWell		;	lda 1,s	; get noun back	sta drawnoun	cmp #$b0	bcs Done	and #$f0	; for specials codes	lsr a	lsr a	lsr a	tax	jsr (wOpTable,x)	bcc Done	bra AnErrorwOpTable	DC.W wDrawText	DC.W SkipIt	DC.W wDrawLine	DC.W wDrawRect	DC.W wDrawRrect	DC.W wDrawOval	DC.W wDrawArc	DC.W wDrawPoly	DC.W wDrawRgn	DC.W wdrawPixel	DC.W wDrawCommentSkipIt	clc	rts	ENDP	title 'Quickdraw Auxilary pics/STDGETPIC'****************************************************************** StdGetPic**       DataPtr  :	Ptr       Points to	where data is to*	          be put.**       Count    :	integer   Number of	bytes to read.** This is the central routine that reads from a picture.* I think this is the only routine that	knows the interal* format of the picture.** Note that the count is an integer.  This means that the* most which can be	read is 64K bytes.	But the picture* format is such that picture size is not so limited.*****************************************************************iStdGetPic	PROC EXPORTRTLAdr	equ 1Count	equ RTLAdr+3sDataPtr	equ Count+2;------------------------------------------------------------;; Lets first see if	there is anything left to read?;	lda PicSize	sec	sbc PlayIndex	tax	lda PicSize+2	sbc PlayIndex+2	bmi NoneLeft	bne SomeStillLeft	cpx #0	bne SomeStillLeftNoneLeft		;	ldx #PicEmpty	bra ERRORSomeStillLeft		;;------------------------------------------------------------;; Copy the pointer and the count to the	stack frame.;	lda sDataPtr,s	sta TempDataPtr	lda sDataPtr+2,s	sta TempDataPtr+2	lda Count,s	sta TempCount;------------------------------------------------------------;; Deref the picture;	jsr DerefPicToDraw;------------------------------------------------------------;; We know that there is more data to read so we set up; CurPtr to point to first byte that will be read.;MoreLeft		;	  ; so we continue	lda PicToDrawPtr	clc	adc PlayIndex	sta PicToDrawPtr	lda PicToDrawPtr+2	adc PlayIndex+2	sta PicToDrawPtr+2;------------------------------------------------------------;; Now we move the bytes.  Note here that the count could be; an odd number so I've written this to work under such; circumstances.;	lda TempCount	; first see if the count is odd	lsr a	bcc Even	; no its even	sep #$30	; move the first byte and	lda [PicToDrawPtr]	sta [TempDataPtr]	rep #$30	IncLong PicToDrawPtr ; and update the pointers and	IncLong TempDataPtr	; counters.	dec TempCount	inc PlayIndexEven		;	  ; The remaining is now even	ldy TempCount	; get how many to move.  If this is	beq OnlyOneByte	; zero, we are now done.	dey	dey	beq OnlyOneWord	; If its zero now then only 1 wordCopyLoop	lda [PicToDrawPtr],y	sta [TempDataPtr],y	dey	dey	bne CopyLoopOnlyOneWord		;	  ; move the last word	lda [PicToDrawPtr]	sta [TempDataPtr];------------------------------------------------------------;; We've read the bytes into the destination and now we; update the pointer to the next byte to read that is; kept at the front	of the picture.;UpdatePlayIndex		;	lda PlayIndex	clc	adc TempCount	sta PlayIndex	bcc NoCarry	inc PlayIndex+2NoCarry		;OnlyOneByte		;	ldx #0	; signal no error;------------------------------------------------------------;; We are done.  Either there was nothing to read and we; will signal an error, or we read it all and there is; no error.  The x register contains what we need to; determine this.;ERROR		;	lda 1,s	; move rtl adr 6 bytes up stack	sta 7,s	; to cover parameters	lda 2,s	sta 8,s	pla	; strip off parameters	pla	pla	txa	; put error code in	a reg	cmp #1	; set carry correctly	rtl	; done	ENDP	title 'Quickdraw Auxilary pics/STDPUTPIC'****************************************************************** StdPutPic**       DataPtr  :	Ptr       Points to	where data is to*	          be taken from.**       Count    :	integer   Number of	bytes to put into pic.** This is the central routine that writes to a picture.* This is one of the few routines that knows the internal* format of the picture.** Note that the count is an integer.  This means that the* most which can be	put into a picture at one time is 64K bytes.* But the picture format is such that picture size is* not so limited.*****************************************************************iStdPutPic	PROC EXPORTPicSave	equ 1CurPtr	equ PicSave+4OrigD	equ CurPtr+4RTLAdr	equ OrigD+2Count	equ RTLAdr+3TheDataPtr	equ Count+2OrigHandle	equ CurPtr	phd	ldy #o_PicSave+2	; push handle to pic save rec on stack	lda [PortRef],y	pha	dey	dey	lda [PortRef],y	pha	lda 3,s	; push it on again so can use	pha	; un referenced handle if	lda 3,s	; needed to set size.	pha	tsc	; turn stack into zp.	tcd;------------------------------------------------------------;; Deref the PicSave	record.  Don't bother locking;	jsr DerefPicSave;------------------------------------------------------------;; Now check to see if there is room in the picture for the; bytes we have to put in.;	ldy #o_PicIndex	; get size of pic	lda [PicSave],y	clc	adc Count	tax	iny	iny	lda [PicSave],y	bcc NoCarry1	inc aNoCarry1		;	  ; a,x has size needed (high in a)	ldy #o_PicMax+2	cmp [PicSave],y	bcc PlentyRoom	beq MoreCheckNeedRoom		;	tay	txa	clc	adc #PicBumpSize	tax	tya	adc #^PicBumpSize	pha	phx	ldy #o_ThePic+2	lda [PicSave],y	pha	dey	dey	lda [PicSave],y	pha	_SetHandleSize	php	; save result status	pha	; save error code	jsr DerefPicSave	pla	; get back error	plp	; get back status	bcc PlentyRoom	tax	brl OutMoreCheck		;	pha	txa	dey	dey	cmp [PicSave],y	bcc PlentyRoomB	tax	pla	bra NeedRoomPlentyRoomB		;	tax	plaPlentyRoom		;;------------------------------------------------------------;; We now know that there is room to put	whatever, so we set	up; CurPtr to point to first byte in pic that will get; new info.;	ldy #o_ThePic	lda [PicSave],y	sta CurPtr	iny	iny	lda [PicSave],y	sta CurPtr+2	ldy #2	; deref pic ptr in place	lda [CurPtr],y	tax	lda [CurPtr]	sta CurPtr	stx CurPtr+2;------------------------------------------------------------;; Update the count at the front of the picture now.;	lda [CurPtr]	clc	adc Count	sta [CurPtr]; Harry and Mensch; The compare below was a BVC which clipped the buffer at 32k, since the commants seem to indicate ; that the max buffer size is 64K we have increased the limit to 64K here by using a bcc instead.; This fixes most apps which would do a prpixelmap of the entire screen area since most of them ; required $8064 bytes if the pic buffer to work.	bcc NoWrap	; if it wraps beyond 64k	lda #$FFFF	; we peg this count	at 64k	sta [CurPtr]NoWrap		;	ldy #o_PicIndex	lda [PicSave],y	clc	; we do full 32 bit	add to create	adc CurPtr	; pointer to next byte of data.	sta CurPtr	iny	iny	lda [PicSave],y	adc CurPtr+2	sta CurPtr+2;------------------------------------------------------------;; Now we move the bytes.  Note here that the count could be; an odd number so I've written this to work under such; circumstances.;	lda Count	; first see if the count is odd	lsr a	bcc Even	; no its even	sep #$30	; move the first byte and	lda [TheDataPtr]	sta [CurPtr]	rep #$30	IncLong TheDataPtr	; and update the pointers and	IncLong CurPtr	; counters.	dec Count	ldy #o_PicIndex	lda [PicSave],y	inc a	sta [PicSave],y	bne NoCarry2	iny	iny	lda [PicSave],y	inc a	sta [PicSave],yNoCarry2		;Even		;	  ; The remaining is now even	ldy Count	; get how many to move.  If this is	beq OnlyOneByte	; zero, we are now done.	dey	dey	beq OnlyOneWord	; If its zero now then only 1 wordCopyLoop	lda [TheDataPtr],y	sta [CurPtr],y	dey	dey	bne CopyLoopOnlyOneWord		;	  ; move the last word	lda [TheDataPtr]	sta [CurPtr]OnlyOneByte		;;------------------------------------------------------------;; We've read the bytes into the destination and now we; update PicIndex in the PicSave record.;	ldy #o_PicIndex	lda [PicSave],y	clc	adc Count	sta [PicSave],y	bcc NoCarry	iny	iny	lda [PicSave],y	inc a	sta [PicSave],yNoCarry		;	ldx #0	; signal no error;------------------------------------------------------------;; We are done.  Either there was nothing to read and we; will signal an error, or we read it all and there is; no error.  The x register contains what we need to; determine this.;Out	pla	; strip off 8 bytes	I put on here	pla	pla	pla	pld	; restore direct reg	lda 1,s	; move rtl adr 6 bytes up stack	sta 7,s	; to cover parameters	lda 2,s	sta 8,s	pla	; strip off parameters	pla	pla	txa	; put error code in	a reg	cmp #1	; set carry correctly	rtl	; done;------------------------------------------------------------;;DerefPicSave		;	ldy #2	lda [OrigHandle],y	sta PicSave+2	lda [OrigHandle]	sta PicSave	rts	ENDP	title 'Quickdraw Auxilary pics/COMMENTS'****************************************************************** PicComment**      Kind : integer*      Size : integer*      DataHandle :	handle** This is the routine called by an application to put a comment* into a picture.*****************************************************************iPicComment	PROC EXPORTOrigD	equ 1RTL1	equ OrigD+2RTL2	equ RTL1+3DataHandle	equ RTL2+3DataSize	equ DataHandle+4DataKind	equ DataSize+2	jsr PicsQDStart	lda DataKind,s	; move the inputs to zero page	sta Y1	lda DataSize,s	sta X1	lda DataHandle,s	sta Y2	lda DataHandle+2,s	sta X2	lda #o_StdComment	; call std play	jsl CallStdPlay	tax	jml BusyErr8	ENDP****************************************************************** rDrawComments** This is the routine that is called when we discover a* comment in the picture.** Change History** 3 Jul 87     SEG** Routine called MyNewHandle instead of	MyWNewHandle as a* routine running during draw picture should.  Result was* handle had invalid user id.** Stack was not setup right for CallGetPic.  DestPtr was* on stack but not the size to read.** Error handling was not cleaning up the stack right at all.** Routine did not know what zero page it had.  It was putting* information that need to be xfered to	the StdComment routine* on direct page without switching direct page in.*****************************************************************rDrawComment	PROC EXPORT	DefineStackHandleInfo	LONGSizeInfo	wordKindInfo	word	jsr GetPicWord	; get the kind	bcs Error0	pha	jsr GetPicWord	; get the size	bcs Error2	pha	jsr MyWNewHandle	; of this size	bcs Error4	phx	; put the handle on	the stack	pha	sta TempDataPtr	; and in tempDataPtr	stx TempDataPtr+2	ldy #4	; so can lock it	lda [TempDataPtr],y	ora #$8000	sta [TempDataPtr],y	dey	; push deref'ed ptr on stack	dey	lda [TempDataPtr],y	pha	lda [TempDataPtr]	pha	lda SizeInfo+4,s	; get size on stack	again	pha	jsl CallGetPic	bcs Error8	lda HandleInfo,s	; restore TempDataPtr and	sta TempDataPtr	lda HandleInfo+2,s	sta TempDataPtr+2	ldy #4	; unlock the handle	lda [TempDataPtr],y	and #$7FFF	sta [TempDataPtr],y	phd	; switch in quickdraw's dp	lda QuickDrawD	tcd	ply	; hold direct in y so can pull;		; inputs off the stack	pla	; first the handle goes in	sta Y2	; Y2	pla	sta Y2+2	pla	; now the size goes	in X1	sta X1	pla	; finally, the kind	goes in Y1	sta Y1	pei Y2+2	; put handle back on stack so can	pei Y2	; get disposed of	phy	; direct back on stack	lda #o_StdComment	; call std play	jsl CallStdPlay	pld	; restore d page	plx	; get handle off stack	ply	pha	; save error code	phy	; put handle back on stack and	phx	; dispose of it.	_DisposeHandle	; dispose of handle	on stack	pla	cmp #0	; fix carry	rtsError8	plx	; handle is on stack	ply	pha	; save error code	phy	; dispose of handle	phx	_DisposeHandle	pla	; get back error codeError4	plxError2	plx	sec	; set carryError0	rts	; done	ENDP****************************************************************** StdComment**        kind*        DataSize*        DataHandle** This is the routine that processes comments.** Change History** 3 Jul 87     SEG** This routine was just calling PutPicStuff and quitting.* This left the opLongComment op-code in the a-reg and* made it seem like	an error.** We now look at carry and clear the a-reg if the carry* is clear.  We return the error code in a-reg if carry* is set.*****************************************************************iStdComment	PROC EXPORT	lda #PicLongComment	jsl PutPictStuff	bcs Error	lda #0Error	rtl	ENDP****************************************************************** wDrawComment** This is the routine that eventually gets called after* someone calls PicComment.*****************************************************************wDrawComment	PROC EXPORT;------------------------------------------------------------;; First I put in the picture field type.;	lda #PicLongComment	jsr PutPicWord	bcs Error;------------------------------------------------------------;; Next I put in the	DataKind and data size	lda Y1	; Kind	jsr PutPicWord	bcs Error	lda X1	; Length	jsr putpicWord	bcs Error;------------------------------------------------------------;; Finally I put in the comment data itself.;	lda Y2	sta Temp	lda X2	sta Temp+2	jsr LockTemp	jsr DerefTempToTemp2 ; deref it into temp2	pei Temp2+2	; prepare to call StdPutPix	pei Temp2	pei X1	jsl CallPutPic	php	; save error state	pha	; save error code	jsr UnlockTemp	pla	; get back error code	plp	; get back error stateError	rts	ENDP****************************************************************** LockTemp** Local routine to lock the handle in temp.*****************************************************************LockTemp	PROC EXPORT	ldy #4	; lock this handle	lda [Temp],y	ora #$8000	sta [Temp],y	rts	ENDP****************************************************************** UnlockTemp** Local routine to unlock the handle in	temp.*****************************************************************UnlockTemp	PROC EXPORT	ldy #4	; unlock the handle	we locked.	lda [Temp],y	and #$7FFF	sta [Temp],y	rts	ENDP	title 'Quickdraw Auxilary pics/UPDATESTATEREC'****************************************************************** UpdateStateRec**      input:  a-reg has drawing noun*              TEMP	has picture handle*              TEMP2 has picture pointer*** This is the routine which compares the current graf port* It is called on only when we know we are about to put a* drawing command into the picture.** If we add anything to the picture we must be careful to* deref the handle again.** Change History**   22 May 87   SEG**   The code that was checking the origin was wrong.    It calculated*   deltaX and deltaY backwards (sign was wrong) and it pushed*   the two values on the stack backwards.**   Both these problems were diagnosed and found by Luc B.**   19 Jan 88   Steven Glass**   Fixed bug in UpdateStateRec related	to text drawing.*   When the grafport had no font id in	it, the fontid that	was*   constructed was	not correct.  The size part of the id was*   made from the style word in the font header rather than	the*   size word.*****************************************************************UpdateStateRec	PROC EXPORT	pha	; save noun on stack;------------------------------------------------------------;; Start looking at the various grafport	fields.;	ldy #o_pnVis	lda [PortRef],y	cmp #-1	bpl pen_ok	; any less than -1 we don't bother.	pla	; pull noun off stack	clc	rts	; and quit nowpen_ok		;;------------------------------------------------------------;; We check the clip	region no matter what we are drawing.;	pei RgnHandleA+2	; this gets zapped so save it	pei RgnHandleA	pha	; make room for function result	jsr PushRgnPtrs	_EqualRgn	pla	bne WereEqual	; they were equal, nothing to do	jsr PushRgnPtrs	; not equal so copy	ClipRgn to	_CopyRgn	; rgn in state record	bcc NoCopyErrRgnError	plx	; restore initial values	stx RgnHandleA	plx	stx RgnHandleA+2	brl Error2NoCopyErr		;	jsr PushClipRgn	; now put the clip region in the	plx	; picture.	ply	lda #PicClipRgn	jsr PutPicRgnB	bcs RgnErrorWereEqual		;	pla	; restore initial values	sta RgnHandleA	pla	sta RgnHandleA+2	jsr DerefPicSave	; Temp and Temp2 must be reset;------------------------------------------------------------;; After checking the region, we check to see if the origin has; changed.;	ldy #o_PortRect	lda [PortRef],y	ldy #o_PicOrigin	cmp [Temp2],y	bne OriginChanged	ldy #o_PortRect+2	lda [PortRef],y	ldy #o_PicOrigin+2	cmp [Temp2],y	beq NoOriginChangeOriginChanged		;	ldy #o_PortRect+2	; new origin goes on the stack	lda [PortRef],y	; x value first	pha	dey	dey	lda [PortRef],y	pha	; now y value	ldy #o_PicOrigin+2	; old origin goes on the stack	lda [TEMP2],y	; x value	pha	dey	dey	lda [TEMP2],y	pha	; now y value	lda 5,s	; state record is updated	sta [TEMP2],y	lda 7,s	iny	iny	sta [TEMP2],y;--------------------------------------------------------------;; Calculate DeltaY and DeltaX as New-Old; (Changed 22 May 87:  was Old-New	lda 5,s	; calculate delta y	sec	sbc 1,s	tax	lda 7,s	; calculate delta x	sec	sbc 3,s	ply	; clear the stack	ply	ply	ply;--------------------------------------------------------------;; Changed on 22 May	87; Was pushing delta	Y before Delta X;	pha	; push delta x	phx	; push delta y	PushWord #PicOrigin	tsc	inc a	pea 0	pha	PushWord #6	jsl CallPutPic	plx	; remove the 6 bytes from stack	plx	plx	bcc NoOriginError	brl Error2NoOriginError	jsr DerefTemptoTemp2 ; re-deref the handle since it may moveNoOriginChange		;;------------------------------------------------------------;; Look at the draw noun and see if it has anything to; do with text.  If	it does, update the	TextPart of the; state record.;; Text fields to look at include:;; Font         -]; FontID       -]  Treated as one; FontFlags; TxSize; TxFace; TxMode; SpExtra; ChExtra; FGColor; BGColor;;	lda 1,s	; draw noun is zero	for text?	beq CheckTextState	brl SkipTextStateCheckTextState		;;------------------------------------------------------------;; FontFlags;	ldy #o_FontFlags	; look at field in port	lda [PortRef],y	;	ldy #o_PicFontFlags	; compare to field in state record	cmp [TEMP2],y	beq FontFlags_OK	; if equal then all	done	sta [TEMP2],y	; else update the state record.	tax	lda #PicFontFlags	jsr PutPicLong	BranchOnError Error2	jsr DerefTempToTemp2 ; deref again since it may have movedFontFlags_ok		;;------------------------------------------------------------;; TxSize;	ldy #o_TxSize	; look at field in port	lda [PortRef],y	;	ldy #o_PicTxSize	; compare to field in state record	cmp [TEMP2],y	beq TxSize_OK	; if equal then all	done	sta [TEMP2],y	; else update the state record.	tax	lda #PicTxSize	jsr PutPicLong	BranchOnError Error2	jsr DerefTempToTemp2 ; deref again since it may have movedTxSize_ok		;;------------------------------------------------------------;; TxFace;	ldy #o_TxFace	; look at field in port	lda [PortRef],y	;	ldy #o_PicTxFace	; compare to field in state record	cmp [TEMP2],y	beq TxFace_OK	; if equal then all	done	sta [TEMP2],y	; else update the state record.	tax	lda #PicTxFace	jsr PutPicLong	BranchOnError Error2	jsr DerefTempToTemp2 ; deref again since it may have movedTxFace_ok		;;------------------------------------------------------------;; TxMode;	ldy #o_TxMode	; look at field in port	lda [PortRef],y	;	ldy #o_PicTxMode	; compare to field in state record	cmp [TEMP2],y	beq TxMode_OK	; if equal then all	done	sta [TEMP2],y	; else update the state record.	tax	lda #PicTxMode	jsr PutPicLong	BranchOnError Error2	jsr DerefTempToTemp2 ; deref again since it may have movedTxMode_ok		;;------------------------------------------------------------;; SpExtra;	ldy #o_SpExtra+2	; get high word of font id in x	lda [PortRef],y	tax	dey	dey	lda [PortRef],y	; get low word of font id in a	ldy #o_PicSpExtra	cmp [TEMP2],y	; compare low word with state record	bne SpExtraChanged	; not the same so save it	txa	iny	iny	cmp [TEMP2],y	; check high word	beq SpExtra_ok	; both ok	bra SpExtraChanged2	; only high word changedSpExtraChanged		;	sta [TEMP2],y	txa	iny	inySpExtraChanged2	sta [TEMP2],y	ldy #o_PicSpExtra+2	; not put the id in	the picture	lda [TEMP2],y	pha	dey	dey	lda [TEMP2],y	pha	lda #PicSpExtra	jsr PutPicWord	BranchOnError Error6	pla	plx	jsr PutPicLong	BranchOnError Error2	jsr DerefTempToTemp2 ; Deref again, it may have moved.SpExtra_OK		;;------------------------------------------------------------;; ChExtra;	ldy #o_ChExtra+2	; get high word of font id in x	lda [PortRef],y	tax	dey	dey	lda [PortRef],y	; get low word of font id in a	ldy #o_PicChExtra	cmp [TEMP2],y	; compare low word with state record	bne ChExtraChanged	; not the same so save it	txa	iny	iny	cmp [TEMP2],y	; check high word	beq ChExtra_ok	; both ok	bra ChExtraChanged2	; only high word changedChExtraChanged		;	sta [TEMP2],y	txa	iny	inyChExtraChanged2	sta [TEMP2],y	ldy #o_PicChExtra+2	; not put the id in	the picture	lda [TEMP2],y	pha	dey	dey	lda [TEMP2],y	pha	lda #PicChExtra	jsr PutPicWord	BranchOnError Error6	pla	plx	jsr PutPicLong	BranchOnError Error2	jsr DerefTempToTemp2 ; Deref again, it may have moved.ChExtra_OK		;;------------------------------------------------------------;; FGColor;	ldy #o_FGColor	; look at field in port	lda [PortRef],y	;	ldy #o_PicFGColor	; compare to field in state record	cmp [TEMP2],y	beq FGColor_OK	; if equal then all	done	sta [TEMP2],y	; else update the state record.	tax	lda #PicFGColor	jsr PutPicLong	BranchOnError Error2	jsr DerefTempToTemp2 ; deref again since it may have movedFGColor_ok		;;------------------------------------------------------------;; BGColor;	ldy #o_BGColor	; look at field in port	lda [PortRef],y	;	ldy #o_PicBGColor	; compare to field in state record	cmp [TEMP2],y	beq BGColor_OK	; if equal then all	done	sta [TEMP2],y	; else update the state record.	tax	lda #PicBGColor	jsr PutPicLong	BranchOnError Error2	jsr DerefTempToTemp2 ; deref again since it may have movedBGColor_ok		;;------------------------------------------------------------;; FontID's are a bit tricky.  If the FontID is zero then; we put the current fonts ID into the state record rather; than the ID from the graf port.;; We do them last here so that when reading the picture; back all the other fields of the graf	port will be; correctly set before I get to the FontID.;	ldy #o_FontID	; first look at font id in grafport	lda [PortRef],y	; if its non-zero then all is well	iny	iny	ora [PortRef],y	bne IDNotZero;; Added 3/15/89 for fastfont compatability	jsl GetportFontPtr	; get a pointer to the realfont in temp2		ldy #6	; offset of size in	font	lda [TEMP2],y	xba	; put into format of FontID	pha	ldy #2	; offset of fontid word in font	lda [TEMP2],y	pha	jsr DerefTempToTemp2	pla	plx	bra JoinHereIDNotZero		;	ldy #o_FontID+2	; get high word of font id in x	lda [PortRef],y	tax	dey	dey	lda [PortRef],y	; get low word of font id in aJoinHere	ldy #o_PicFontID	cmp [TEMP2],y	; compare low word with state record	bne IDChanged	; not the same so save it	txa	iny	iny	cmp [TEMP2],y	; check high word	beq FontID_ok	; both ok	bra IDChanged2	; only high word changedIDChanged		;	sta [TEMP2],y	txa	iny	inyIDChanged2	sta [TEMP2],y	ldy #o_PicFontID+2	; not put the id in	the picture	lda [TEMP2],y	pha	dey	dey	lda [TEMP2],y	pha	lda #PicTxFont	jsr PutPicWord	BranchOnError Error2	pla	plx	jsr PutPicLong	BranchOnError Error2	jsr DerefTempToTemp2 ; Deref again, it may have moved.FontID_ok		;SkipTextState		;;------------------------------------------------------------;; Look at the drawing noun and see if it is a object drawn; with patterns.;	lda 1,s	beq NotPatObj	cmp #RgnNoun+$10	bcc PatternObjectNotPatObj	brl SkipPatternObjectPatternObject		;;------------------------------------------------------------;; Here we check the	fields releated to objects drawn with; patterns.  These are;; PnMode   (only for paint, frame and lines); ThePat   (a very tricky one); DrawingMask; PenSize  (only if	framing or drawing lines); PenLocation (if drawing lines);;------------------------------------------------------------;; PnMode;	lda 1,s	cmp #LineNoun	beq NeedMode	lda DrawVerb	beq NeedMode	; need mode for frames	cmp #PaintVerb	; need mode for paint	bne PnMode_OK	; don't need mode for anything else.NeedMode		;	ldy #o_PnMode	; look at field in port	lda [PortRef],y	;	ldy #o_PicPnMode	; compare to field in state record	cmp [TEMP2],y	beq PnMode_OK	; if equal then all	done	sta [TEMP2],y	; else update the state record.	tax	lda #PicPnMode	jsr PutPicLong	BranchOnError Error2	jsr DerefTempToTemp2 ; deref again since it may have movedPnMode_ok		;;------------------------------------------------------------;; PnPat    \; BkPat     | -- Which one depends on drawing verb; ThePat   /;	lda 1,s	; if it is a line then don't	cmp #$30	; look at verb.	bcs NotALine	stz DrawVerb	; treat like frameNotALine	lda DrawVerb	cmp #InvertVerb	beq ThePat_OK	cmp #FillVerb	beq PatInPlace	cmp #EraseVerb	bne UsePnPat	jsl Back2ZP	bra PatInPlaceUsePnPat	jsl Pen2ZPPatInPlace		;	lda DrawVerb	asl a	tax	lda >PatOffsetTable,x	tay	ldx #256	lda DrawVerb	; The fill pattern is always put in	cmp #FillVerb	; the picture.	beq DiffPatThePatLoop	lda TheFillPat,x	cmp [TEMP2],y	bne DiffPat	inx	inx	iny	iny	cpx #256+32	bcc ThePatLoop	bra ThePat_OKDiffPat		;	  ; update right pattern in state record;		; they were same 'til herePatUpdateLoop	lda TheFillPat,x	sta [TEMP2],y	iny	iny	inx	inx	cpx #256+32	bcc PatUpdateLoop	lda DrawVerb	asl a	tax	lda >PatOpTable,x	jsr PutPicWord	BranchOnError Error2	pea 0	tdc	clc	adc #256+TheFillPat	pha	PushWord #32	jsl CallPutPic	BranchOnError Error2	jsr DerefTempToTemp2 ; deref again in case it moved.ThePat_ok		;;------------------------------------------------------------;; PnMask;	ldy #o_PnMask	ldx #o_PicPnMaskPnMaskLoop	lda [PortRef],y	phy	txy	cmp [TEMP2],y	bne DiffMask	iny	iny	tyx	ply	iny	iny	cpy #o_PnMask+8	bcc PnMaskLoop	bra PnMask_OKDiffMaskLoop		;	lda [PortRef],y	phy	txyDiffMask	sta [TEMP2],y	; copy this and all	rest into state	iny	iny	tyx	ply	iny	iny	cpy #o_PnMask+8	bcc DiffMaskLoop	lda #PicPnMask	; now put in picture.	jsr PutPicWord	BranchOnError Error2	lda PortRef	clc	adc #o_PnMask	tax	lda PortRef+2	adc #0	pha	phx	PushWord #8	jsl CallPutPic	BranchOnError Error2	jsr DerefTempToTemp2 ; deref again in case it moved.PnMask_ok		;;------------------------------------------------------------;; PnSize;	ldy #o_PnSize+2	; get high word of font id in x	lda [PortRef],y	tax	dey	dey	lda [PortRef],y	; get low word of font id in a	ldy #o_PicPnSize	cmp [TEMP2],y	; compare low word with state record	bne PnSizeChanged	; not the same so save it	txa	iny	iny	cmp [TEMP2],y	; check high word	beq PnSize_ok	; both ok	bra PnSizeChanged2	; only high word changedPnSizeChanged		;	sta [TEMP2],y	txa	iny	inyPnSizeChanged2	sta [TEMP2],y	ldy #o_PicPnSize+2	; not put the id in	the picture	lda [TEMP2],y	pha	dey	dey	lda [TEMP2],y	pha	lda #PicPnSize	jsr PutPicWord	BranchOnError Error6	pla	plx	jsr PutPicLong	BranchOnError Error2	jsr DerefTempToTemp2 ; Deref again, it may have moved.PnSize_OK		;;------------------------------------------------------------;; ArcRot;	ldy #o_ArcRot	; look at field in port	lda [PortRef],y	;	ldy #o_PicArcRot	; compare to field in state record	cmp [TEMP2],y	beq ArcRot_OK	; if equal then all	done	sta [TEMP2],y	; else update the state record.	tax	lda #PicArcRot	jsr PutPicLong	BranchOnError Error2	jsr DerefTempToTemp2 ; deref again since it may have movedArcRot_ok		;SkipPatternObject		;;------------------------------------------------------------;; All done.  Pull noun off stack and rts;	pla	clc	rtlError6	plxError4	plxError2	plx	rtlPatOffsetTable		;         ; frame	DC.W o_PicPnPat	DC.W o_PicPnPat	DC.W o_PicBkPat	DC.W o_PicFillPat	DC.W o_PicFillPatPatOpTable		;           ; frame	DC.W PicPnPat	DC.W PicPnPat	DC.W PicBkPat	DC.W 0	DC.W PicThePatPushRgnPtrs		;	plx	ldy #o_ClipRgn+2	lda [PortRef],y	pha	dey	dey	lda [PortRef],y	phaJoinRgn	ldy #o_PicClipRgn+2	lda [TEMP2],y	pha	dey	dey	lda [TEMP2],y	pha	phx	rtsPushClipRgn		;	plx	bra joinRgn	ENDP********************************************************************************************************************************************	title 'Quickdraw Auxilary pics/PICUTILS'		EJECT********************************************************************************GetportFontPtr	PROC** Description:	This routine derefs the current grafports font handle and*	returns the derefed version of it in fontHeadPtr. This should*	be called by any routine that wants to look at the font *	record directly. It knows about fast fonts, and it knows how* 	to use them!** NOTE:	*** Inputs:	NotMuch** Outputs:	FontHeadPtr** External Refs:;; Equates for the fastfont record;o_FFAscent	equ 0o_FFDescent	equ o_FFAscent+2o_FFMaxWidth	equ o_FFDescent+2o_FFLeading	equ o_FFMaxWidth+2o_FFrowBytes	equ o_FFLeading+2o_oldFontHandle	equ o_FFRowBytes+2o_StrikeSize	equ o_oldFontHandle+4o_FFSizeofVars	equ o_StrikeSize+4o_FFWidthTable	equ o_FFSizeofVarso_FFOffsetTable	equ o_FFWidthTable+256o_FFEndOfTables	equ o_FFOffsetTable+512;** Entry Points:********************************************************************************	ldy #(O_font+2)	lda [PortRef],y	;font handle high word	bpl standardFont	; if high bit clear we are using a standard font	loadStdData	sta Temp2+2	; get the handle to the fastfont stuff	ldy #o_font	lda [PortRef],y	sta Temp2	lda [Temp2]	; and deref it... we now have the pointer...	tax	ldy #2	lda [Temp2],y	sta Temp2+2	stx Temp2; Now get the handle to the original font from here!	ldy #o_oldFontHandle ; offset to the old font..	lda [Temp2],y	; get the old font handle	tax	ldy #o_oldFontHandle+2	lda [Temp2],y	sta Temp2+2	; set temp to be the old font handle	stx Temp2	bra SF0010	; and branch into standard font stuff	standardFont	sta Temp2+2	dey	dey	lda [PortRef],y	sta Temp2;SF0010	lda [TEMP2]	tax	ldy #2	lda [TEMP2],y	sta TEMP2+2	stx TEMP2	rtl	EndP****************************************************************** MyNewHandle** Routine to return	a new handle of size passed in a-reg** Handle is returned in a,x (a low, x high).*****************************************************************MyNewHandle	PROC EXPORT	pha	; space for result	pha	pea 0	; size	pha	pei UserID	pea 0	; attributes	pha	; junk for space	pha	_NewHandle	pla	plx	rts	ENDP****************************************************************** MyWNewHandle** Routine to return	a new handle of size passed in a-reg** Handle is returned in a,x (a low, x high).** This is different	than MyNewHandle in	that QuickDraw's* zero page is not switched in when it is called.  We* must work harder to get the*****************************************************************MyWNewHandle	PROC EXPORT	phd	tay	; save size in y	lda QuickDrawD	Export JoinTrickyNewHandleJoinTrickyNewHandle	tcd	tya	; get size back	jsr MyNewHandle	pld	rts	ENDP****************************************************************** DerefPicSave** Takes the PicSave	field and puts it into TEMP.  then* falls into DerefTempToTemp2.*****************************************************************DerefPicSave	PROC EXPORT	ldy #o_PicSave	lda [PortRef],y	sta temp	iny	iny	lda [PortRef],y	sta temp+2; now fall into DerefTempToTemp2	ENDP****************************************************************** DerefTempToTemp2** Dereferences the handle in TEMP putting pointer in TEMP2* Does not lock the	handle since it assumes that no calls which* would cause it to	move will be made while looking at data.*****************************************************************DerefTempToTemp2	PROC EXPORT	lda [Temp]	; deref temp to temp2	sta Temp2	ldy #2	lda [Temp],y	sta Temp2+2	rts	ENDP****************************************************************** DerefTempDataPtr** This routine derefs the handle an TempDataPtr and puts result* in tempdataptr.*****************************************************************DerefTempDataPtr	PROC EXPORT	ldy #2	lda [TempDataPtr],y	tax	lda [TempDataPtr]	sta TempDataPtr	stx TempDataPtr+2	rts	ENDP****************************************************************** PutPicByte** Puts the byte passed in the a register into the picture.* If an write error	occurs, the error is returned.*****************************************************************PutPicByte	PROC EXPORT	pha	; put it on the stack	tsc	; get stack pointer	inc a	; one more and it points to word	pea 0	; high word of pointer to this	pha	; Now push this	PushWord #1	jsl CallPutPic	plx	; error preserved in a if any	rts	ENDP****************************************************************** GetPicByte** Returns the next byte from picture in	the a register.  If	a read* error occurs, the	error is returned.*****************************************************************GetPicByte	PROC EXPORT	pha	; push space on stack for result	tsc	; get stack pointer	inc a	; bump by one to get pointer to that;		; word	pea 0	; high word of pointer to word	pha	; low word of pointer to word	PushWord #1	jsl CallGetPic	bcs error	pla	and #$00FF	rtsError	plx	rts	ENDP****************************************************************** PutPicWord** Puts the word passed in the a register into the picture.* If an write error	occurs, the error is returned.*****************************************************************PutPicWord	PROC EXPORT	pha	; put it on the stack	tsc	; get stack pointer	inc a	; one more and it points to word	pea 0	; high word of pointer to this	pha	; Now push this	PushWord #2	jsl CallPutPic	plx	; error preserved in a if any	rts	ENDP****************************************************************** GetPicWord** Returns the next from picture in the a register.  If a read* error occurs, the	error is returned.*****************************************************************GetPicWord	PROC EXPORT	pha	; push space on stack for result	tsc	; get stack pointer	inc a	; bump by one to get pointer to that;		; word	pea 0	; high word of pointer to word	pha	; low word of pointer to word	PushWord #2	jsl CallGetPic	bcs error	pla	rtsError	plx	rts	ENDP****************************************************************** PutPicLong** Puts the long passed in the a and x registers into the picture.* If an write error	occurs, the error is returned.*****************************************************************PutPicLong	PROC EXPORT	phx	pha	; put it on the stack	tsc	; get stack pointer	inc a	; one more and it points to word	pea 0	; high word of pointer to this	pha	; Now push this	PushWord #4	jsl CallPutPic	plx	; error preserved in a if any	plx	rts	ENDP****************************************************************** GetPicLong** Returns the next Long from picture in	the a and x register.  If a read* error occurs, the	error is returned.*****************************************************************GetPicLong	PROC EXPORT	pha	; push space on stack for result	pha	tsc	; get stack pointer	inc a	; bump by one to get pointer to that;		; word	pea 0	; high word of pointer to word	pha	; low word of pointer to word	PushWord #4	jsl CallGetPic	bcs error	pla	plx	rtsError	plx	plx	rts	ENDP****************************************************************** GetPicOpCode** Returns the opcode from the picture.	How it reads the opcode* depends on the version number.  A version number with low* nibble of 1 implies a 1 byte opcode.	All other verions have* two byte opcodes.*****************************************************************GetPicOpCode	PROC EXPORT	lda ThisVersion	and #$000F	cmp #1	beq DoByte	jsr GetPicWord	rtlDoByte	jsr GetPicByte	rtl	ENDP****************************************************************** CallPutPic** This routine transfers control to the	appropriate version* of PutPic.  It checks the grafprocs and if they exist it* uses them.  If they don't exist then it jumps directly to* StdPutPic.** Change History** May 22, 1987  SEG** Some routines were foolishly relying on TEMP2 being preserved* accross these calls so now I preserve	it.** This problem was diagnosed and found by Luc B.*****************************************************************CallputPic	PROC EXPORT;	*** Debugging code, 28-Nov-90 DAL;	*** the pointer to the stuff to put is at 6,s to 9,s;		pha;		pha	;pushed 4 bytes return space;		lda 8+4,s	;high word of input ptr;		pha;		lda 6+6,s	;low word ofinput ptr;		pha;		_FindHandle;		phd;		tsc;		tcd;		bcs @bad	;carry from _FindHandle;		ldy #4	;offset to attributes;		lda [3],y;		bmi @okay;		and #$4300;		cmp #$4000;		beq @okay;	@bad	brk $42;	@okay	pld	;restore D;		pla	;pull old stuff;		pla;	*** end debug, 28-Nov-90 DAL	pei Temp2+2	; save Temp2	pei Temp2	ldy #o_grafProcs	; start by looking at the	lda [PortRef],y	; grafprocs pointer.	sta Temp2	; (put it in temp2 for later	iny	; use if necessary)	iny	lda [PortRef],y	sta Temp2+2	ora Temp2	; is it nil	bne UseGrafProcs	; no, use it	pla	; restore temp2	sta Temp2	pla	sta Temp2+2	jml StdPutPic	; is nil so jmp straight to StdPutPicsUseGrafProcs		;	  ; use the graf procs record	pha	; put 3 bytes on the stack	phbOrigTemp2	equ 3+1NewTemp2	equ 1RTLAddr	equ 1+4	lda OrigTemp2,s	; move value of temp 2 3 bytes	sta NewTemp2,s	; down stack	lda OrigTemp2+2,s	sta NewTemp2+2,s	ldy #o_StdPutPic+1	; get middle and high bytes on stack	lda [temp2],y	sta RTLAddr+1,s	dey	; now get low and middle in a reg	lda [temp2],y	sta RTLAddr,s	; overstore low and	middle bytes	pla	; restore Temp2	sta Temp2	pla	sta Temp2+2	rtl	; RTL to that address.	ENDP****************************************************************** CallGetPic** This routine transfers control to the	appropriate version* of GetPic.  It checks the grafprocs and if they exist it* uses them.  If they don't exist then it jumps directly to* StdGetPic.** Trashes TempDataPtr in play state record*****************************************************************CallGetPic	PROC EXPORT	ldy #o_grafProcs	; start by looking at the	lda [CurPortRef],y	; grafprocs pointer.	sta TempDataPtr	; (put here for later	iny	; use if necessary)	iny	lda [CurPortRef],y	sta TempDataPtr+2	ora TempDataPtr	; is it nil	bne UseGrafProcs	; no, use it	jml StdGetPic	; is nil so jmp straight to StdPutPicsUseGrafProcs		;	  ; use the graf procs record	ldy #o_StdGetPic+1	; get middle and high bytes on stack	lda [TempDataPtr],y	pha	dey	; now get low and middle in a reg	lda [TempDataPtr],y	phb	; put trash byte on	stack	sta 1,s	; overstore low and	middle bytes	rtl	; RTL to that address.	ENDP****************************************************************** CallStdPlay** Input:  a-reg has	which std field in graf procs record** This routine transfers control to the	appropriate Std* drawing routine.** Note:  Even though this routine is called by the play routines*        it is called after the quickdraw zero page is switched*        back in so	it uses PortRef and	TEMP2.** Trashes TEMP2 in play state record*****************************************************************CallStdPlay	PROC EXPORT	pha	; save field	ldy #o_grafProcs	; start by looking at the	lda [PortRef],y	; grafprocs pointer.	sta TEMP2	; (put it here for later	iny	; use if necessary)	iny	lda [PortRef],y	sta TEMP2+2	ora TEMP2	; is it nil	bne UseGrafProcs	; no, use it	plx	lda >ProcTable+1,x	pha	phb	lda >ProcTable,x	sta 1,s	rtlUseGrafProcs		;	  ; use the graf procs record	ply	iny	lda [TEMP2],y	pha	dey	; now get low and middle in a reg	lda [TEMP2],y	phb	; put trash byte on	stack	sta 1,s	; overstore low and	middle bytes	rtl	; RTL to that address.ProcTable		;	DC.L StdText-1	DC.L StdLine-1	DC.L StdRect-1	DC.L StdRRect-1	DC.L StdOval-1	DC.L StdArc-1	DC.L StdPoly-1	DC.L StdRgn-1	DC.L StdPixels-1	DC.L StdComment-1	DC.L StdTxMeas-1	DC.L StdTxBnds-1	DC.L StdGetPic-1	DC.L StdPutPic-1	ENDP****************************************************************** MapThisPt** Maps the point sitting on the stack above the RTS adr* from the PicFrame	to the PlayFrame.*****************************************************************MapThisPt	PROC EXPORTRTSAdr	equ 1PtToMap	equ RTSAdr+2	tsc	clc	adc #PtToMap	pea 0	pha	jsr PushRectPtrs	_MapPt	rts	ENDP****************************************************************** MapThisRect** Maps the rect Passed on the stack right above the RTS value* from the PicFrame	to the PlayFrame.*****************************************************************MapThisRect	PROC EXPORTRTSAdr	equ 1RectToMap	equ RTSAdr+2	tsc	; calculate pointer	to rect to map	clc	adc #RectToMap	pea 0	; high word is 0	pha	; this is low word	jsr PushRectPtrs	_MapRect	rts	ENDP****************************************************************** ScaleThisPt** Scales the point sitting on the stack	above the RTS adr* from the PicFrame	to the PlayFrame.*****************************************************************ScaleThisPt	PROC EXPORTRTSAdr	equ 1PtToScale	equ RTSAdr+2	tsc	clc	adc #PtToScale	pea 0	pha	jsr PushRectPtrs	_ScalePt	rts	ENDP****************************************************************** PushRectPtrs** This routine pushes pointers to the play and frame rects* onto the stack.** Both of these rects are in the stack frame that is current* direct page.*****************************************************************PushRectPtrs	PROC EXPORT	plx	; put rts adr in x	lda #0	; make all four words on stack	pha	; equal to zero	pha	pha	pha	phx	; put rts adr back on stackRtsAdr	equ 1	; stack equatesPtr2	equ RTSAdr+2Ptr1	equ Ptr2+4	tdc	clc	adc #FromRect	sta Ptr1,s	tdc	clc	adc #ToRect	sta Ptr2,s	rts	ENDP****************************************************************** PicsPicsQDStart** This is a local routine that increments the busy flag, saves* the current direct register on the stack and transfers* the a register to	the D register.** This is meant to be called at the start of any QD entry point* that requires zero page and the busy flag to be incremented.** In Doing this we trash the X-Register.  Hopefully this will* not cause anyone any problems.** We do know that A	and Y must be untouched.  Y for PortWord* and PortLong.  A for cursor routines that add $100 to A*****************************************************************PicsQDStart	PROC EXPORT	jsl IncBusyFlg	phd	; push d on stack	tcd	; set d	lda 3,s	; getorig rts	pha	; put on stack	lda 3,s	; move orig d to on	top of rts	sta 5,s	pla	; pull rts off stack	sta 1,s	; put over orig d	tdc	; get QD D back in a	rts	; done	ENDP		END